            uid=item.get('unit_id')
            if uid not in out:
                out.append(uid)
    return out

def term_contains(value,name):
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            if item[0]==name:
                return True
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
