def any_phrase(t,xs):
    for x in xs:
        if x in t:
            return True
    return False

def has_word(t,p):
    return re.search(p,t,re.I) is not None

def add_statement(out,term,support_ids):
    support=unique(support_ids)
    for row in out:
        if row.get('term')==term:
            return
    out.append({'term':term,'support_ids':support})

def add_once(xs,x):
    if x not in xs:
        xs.append(x)

def make_union(items):
    if not items:
        return None
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['participant_union',items[i],value]
        i-=1
    return value

def make_condition(t):
    cs=[]
    if 'need to know' in t or 'need-to-know' in t or 'need-to know' in t:
        cs.append(['need_to_know','stated purpose'])
    if any_phrase(t,['bound by obligations of confidentiality','treat the confidential information as confidential','obliged by their contracts','obligated to protect','terms and conditions no less protective']):
        cs.append(['confidentiality_bound','source-stated confidentiality obligation'])
    if any_phrase(t,['only to the extent necessary','disclosure is necessary','as deemed necessary','reasonably necessary']):
        cs.append(['extent_necessary','source-stated purpose'])
    if not cs:
        return ['no_condition']
    v=cs[0]
    i=1
    while i<len(cs):
        v=['and_condition',v,cs[i]]
        i+=1
    return v

def permission_segment(t):
    marks=['may disclose','may share','internally share','restrict access','except in confidence','except to such']
    best=-1
    for m in marks:
        p=t.rfind(m)
        if p>best:
            best=p
    if best<0 and 'not to disclose' in t and ' except ' in t:
        best=t.rfind(' except ')
    return t[best:] if best>=0 else t

def recipient_terms(t):
    owner=['receiving_party']
    if any_phrase(t,["affiliates' officers","affiliates’ officers","affiliate's officers","affiliate’s officers"]):
        owner=['affiliates_of',['receiving_party']]
    xs=[]
    if has_word(t,r'\bemployees?\b'):
        xs.append(['employees_of',owner])
    if has_word(t,r'\bdirectors?\b'):
        xs.append(['directors_of',owner])
    if has_word(t,r'\bofficers?\b'):
        xs.append(['officers_of',owner])
    if any_phrase(t,['legal advisors','legal advisers','attorneys','legal counsel']):
        xs.append(['legal_advisors_of',owner])
    if any_phrase(t,['financial advisors','financial advisers']):
        xs.append(['financial_advisors_of',owner])
    if any_phrase(t,['professional advisors','professional advisers']):
        xs.append(['professional_advisors_of',owner])
    if has_word(t,r'\baccountants?\b'):
        xs.append(['accountants_of',owner])
    if has_word(t,r'\bconsultants?\b'):
        xs.append(['consultants_of',owner])
    if has_word(t,r'\bagents?\b'):
        xs.append(['agents_of',owner])
    if has_word(t,r'\bcontractors?\b'):
        xs.append(['independent_contractors_of',owner])
    if has_word(t,r'\blenders?\b'):
        xs.append(['lenders_of',owner])
    if 'internally share' in t and not xs:
        xs.append(['internal_personnel_of',['receiving_party']])
    if not xs and 'representatives' in t:
        xs.append(['representatives_of',['receiving_party']])
    if not xs and any_phrase(t,['third parties','third party']):
        xs.append(['third_parties'])
    return xs

def make_exceptions(t,perm):
    es=[]
    if any_phrase(t,['prior written consent','prior, written consent','prior written approval','prior written permission','expressly authorized in writing','express permission']):
        es.append(['authorization_exception','source-stated written authorization'])
    if any_phrase(t,['required to analyze','required to fulfil','required to fulfill']):
        es.append(['purpose_exception','source-stated required activity'])
    if any_phrase(t,['except as expressly permitted under','except as permitted under','except as provided in','except as provided under']):
        es.append(['cross_reference_exception','source-stated disclosure cross-reference'])
    if perm is not None:
        es.append(['permission_exception',perm])
    if not es:
        return ['no_exceptions']
    v=['exception_set',es[0]]
    i=1
    while i<len(es):
        v=['add_exception',v,es[i]]
        i+=1
    return v

def parse_context(raw,ids,out,refs):
    t=raw.casefold()
    if not t:
        return
    if ('“representative” means' in t or '"representative" means' in t or 'representative means' in t) and any_phrase(t,['employee','director','officer','agent','accountant','attorney','contractor']):
        cats=recipient_terms(t)
        fixed=[]
        for c in cats:
            if len(c)>1:
                c[1]=['party']
            fixed.append(c)
        if fixed:
            add_statement(out,['define_representative',['party'],make_union(fixed)],ids)
    if any_phrase(t,['information about employees','employee lists and records','human resources data']) and 'confidential' in t:
        add_statement(out,['confidential_information_includes',['employee_information',['disclosing_party']]],ids)
    if 'whereas' in t and 'may' in t and 'disclos' in t and 'confidential information' in t:
        add_statement(out,['possible_disclosure_description',['disclosing_party'],['confidential_information'],['receiving_party']],ids)
    if 'confidential information' not in t and 'such information' not in t and 'the same' not in t:
        return
    actor=['named_recipient','Volunteer'] if 'volunteer agrees' in t else ['receiving_party']
    if 'neither it nor its representatives' in t and any_phrase(t,['any other person','any other organization','other person or organization']):
        group=['participant_union',['receiving_party'],['representatives_of',['receiving_party']]]
        ex=make_exceptions(t,None)
        add_statement(out,['prohibition',group,['disclose',['confidential_information'],['outsiders_to',group]],['no_condition'],ex],ids)
        return
    pmark=any_phrase(t,['may disclose','may share','internally share','restrict access']) or ('not to disclose' in t and ' except ' in t)
    perm=None
    if pmark:
        seg=permission_segment(t)
        cats=recipient_terms(seg)
        if cats:
            perm=['permission',actor,['disclose',['confidential_information'],make_union(cats)],make_condition(t)]
            add_statement(out,perm,ids)
    third=any_phrase(t,['third parties','third party'])
    neg=any_phrase(t,['shall not disclose','not to disclose','not to, without','not to, directly','not disclose, allow access','not to divulge'])
    if third and neg:
        ex=make_exceptions(t,perm)
        add_statement(out,['prohibition',actor,['disclose',['confidential_information'],['third_parties']],['no_condition'],ex],ids)
        if any_phrase(t,['except as expressly permitted under','except as permitted under','except as provided in','except as provided under']):
            add_once(refs,'unresolved disclosure cross-reference')

def has_tag(term,name):
    todo=[term]
    while todo:
        x=todo.pop()
        if isinstance(x,list) and x:
            if x[0]==name:
                return True
            i=1
            while i<len(x):
                if isinstance(x[i],list):
                    todo.append(x[i])
                i+=1
    return False

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    out=[]
    seed=inputs.get('source_output',{})
    if isinstance(seed,dict):
        for row in seed.get('statements',[]):
            if isinstance(row,dict) and isinstance(row.get('term'),list):
                add_statement(out,row.get('term'),row.get('support_ids',[]))
    texts=[]
    ids=[]
    for span in spans:
        uid=span.get('id')
        raw=span.get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        ids.append(uid)
        texts.append(raw)
        parse_definition(raw,uid,out)
        parse_disclosure(raw,[uid],out)
        parse_disposal(raw,[uid],out)
        parse_retention(raw,uid,out)
    i=0
    while i<len(texts):
        current=lower_text(texts[i])
        disclosure_header=current.endswith(':') and has_any(current,['may disclose','do not apply to the disclosure','shall be handled as follows'])
        if disclosure_header:
            j=i+1
            while j<len(texts) and j<=i+4:
                parse_disclosure(' '.join(texts[i:j+1]),ids[i:j+1],out)
                j+=1
        disposal_header=(current.endswith(':') and has_any(current,['return of confidential information','shall be returned','returned to','return or destroy'])) or (trigger_terms(current) and has_any(current,['return of confidential information','shall return','return to']) and not has_any(current,['or destroy','destroy it','ensure the destruction']))
        if disposal_header:
            j=i+1
            while j<len(texts) and j<=i+4:
                parse_disposal(' '.join(texts[i:j+1]),ids[i:j+1],out)
                j+=1
        i+=1
    return {'statements':out,'complete':True,'unresolved':[]}

def make_information_bundle(xs):
    if len(xs)==1:
        return xs[0]
    v=xs[len(xs)-1]
    i=len(xs)-2
    while i>=0:
        v=['information_bundle',xs[i],v]
        i-=1
    return v

def disposal_information(t):
    xs=[['confidential_information']]
    if 'copy' in t or 'copies' in t:
        xs.append(['copies_of',['confidential_information']])
    if any_phrase(t,['compilation','analysis','derivative work','notes or abstracts','notes and abstracts']):
        xs.append(['derivative_materials_of',['confidential_information']])
    return make_information_bundle(xs)

def retention_information(t):
    xs=[]
    if 'copy' in t or 'copies' in t or 'backup system' in t:
        xs.append(['copies_of',['confidential_information']])
    if any_phrase(t,['notes or abstracts','notes and abstracts','compilation','analysis','derivative work']):
        xs.append(['derivative_materials_of',['confidential_information']])
    if not xs:
        xs.append(['confidential_information'])
    return make_information_bundle(xs)

def disposal_trigger(t):
    xs=[]
    if 'termination of service' in t or 'service terminates' in t:
        xs.append(['service_termination'])
    elif any_phrase(t,['upon termination of this agreement','upon termination of the agreement','termination of this agreement']):
        xs.append(['agreement_termination'])
    if 'completion of the purpose' in t:
        xs.append(['purpose_completion'])
    if (('upon' in t and 'request' in t) or 'receipt of a written request' in t or 'written request from' in t or 'written request of' in t):
        xs.append(['request_by',['disclosing_party']])
    if not xs:
        return None
    v=xs[0]
    i=1
    while i<len(xs):
        v=['trigger_alternative',v,xs[i]]
        i+=1
    return v

def retention_condition_for(t):
    if 'required' in t and 'applicable law' in t:
        return ['retention_condition','record copy required by applicable law']
    if 'archival purpose' in t:
        return ['retention_condition','one copy solely for archival purpose']
    if 'single copy' in t and any_phrase(t,['regulatory compliance','compliance with the terms']):
        return ['retention_condition','single copy for regulatory and agreement compliance']
    if 'single copy' in t:
        return ['retention_condition','single copy for the source-stated purpose']
    return ['retention_condition','source-stated limited retention']

def parse_disposal(raw,support,out):
    text=lower_text(raw)
    if not has_any(text,['confidential information','information disclosed','information provided','copies thereof','materials which']):
        return
    triggers=trigger_terms(text)
    if not triggers:
        return
    do_return=has_any(text,['shall return','return to','returned to','promptly return','information will be returned'])
    do_destroy=has_any(text,['shall be destroyed','or destroy','destroy it','certify the destruction','ensure the destruction','promptly destroy']) and 'not destroyed' not in text
    if not do_return and not do_destroy:
        return
    info=material_scope(text)
    if do_return and do_destroy:
        action=['action_alternative',['return_to',info,['disclosing_party']],['destroy',info]]
    elif do_return:
        action=['return_to',info,['disclosing_party']]
    else:
        action=['destroy',info]
    add_statement(out,['disposal_obligation',actor_for(text),action,trigger_value(triggers),['no_exceptions']],support)

def low(value):
    if not isinstance(value,str):
        value=str(value)
    return value.casefold().strip()

def has_any(text,phrases):
    for phrase in phrases:
        if phrase in text:
            return True
    return False

def unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def make_and(items):
    if not items:
        return ['no_condition']
    value=items[0]
    i=1
    while i<len(items):
        value=['and_condition',value,items[i]]
        i+=1
    return value

def owner_for_definition(term):
    if isinstance(term,list) and len(term)>1:
        term[1]=['party']
    return term

def recipient_items(text,owner):
    items=[]
    if has_any(text,['employee','staff','personnel']):
        items.append(['employees_of',owner])
    if 'director' in text:
        items.append(['directors_of',owner])
    if has_any(text,['officer','official']):
        items.append(['officers_of',owner])
    if has_any(text,['legal adviser','legal advisor','attorney','legal counsel']):
        items.append(['legal_advisors_of',owner])
    if has_any(text,['financial adviser','financial advisor']):
        items.append(['financial_advisors_of',owner])
    if has_any(text,['professional adviser','professional advisor']):
        items.append(['professional_advisors_of',owner])
    if 'accountant' in text:
        items.append(['accountants_of',owner])
    if 'consultant' in text:
        items.append(['consultants_of',owner])
    if 'contractor' in text:
        items.append(['independent_contractors_of',owner])
    if 'agent' in text:
        items.append(['agents_of',owner])
    if has_any(text,['lender','finance provider']):
        items.append(['lenders_of',owner])
    if not items and 'representative' in text:
        items.append(['representatives_of',owner])
    return items

def disclosure_condition(text,raw):
    conditions=[]
    if has_any(text,['need to know','need-to-know','strict need to know','bona fide need']):
        conditions.append(['need_to_know',raw])
    if has_any(text,['extent necessary','extent absolutely necessary','reasonably necessary','disclosure is necessary','knowledge of the confidential information is reasonably necessary']):
        conditions.append(['extent_necessary',raw])
    if has_any(text,['written confidentiality agreement','written agreement with','signed the mandatory non-disclosure agreement','signed the mandatory nondisclosure agreement','bound to a duty of confidentiality','bound by obligations of confidentiality','treat the confidential information as confidential','advise such employees','complies with all the provisions of this agreement','obligated to protect']):
        conditions.append(['confidentiality_bound',raw])
    return make_and(conditions)

def operative_information(text):
    return has_any(text,['confidential information','such confidential information','information it receives from','said information','the same'])

def permission_marker(text):
    return has_any(text,['may disclose','may be disclosed','may share','will disclose information','restrict disclosure','restrict access','disclosed only to','except in confidence to','restrictions in paragraph','restrictions under paragraph'])

def prohibition_marker(text):
    return has_any(text,['shall not disclose','not disclose said information','not to disclose','agrees not to','will not provide confidential information','prohibited from disclosing'])

def actor_for(text):
    if 'volunteer' in text:
        return ['named_recipient','Volunteer']
    if 'auditor' in text and 'receiving party' not in text:
        return ['named_recipient','Auditor']
    if 'visitor' in text and 'receiving party' not in text:
        return ['named_recipient','Visitor']
    return ['receiving_party']

def parse_definition(raw,uid,out):
    text=lower_text(raw)
    if not has_any(text,['representative” means','representatives” means','"representative" means','"representatives" means']):
        return
    roles=recipient_roles(text,['party'])
    if roles:
        add_statement(out,['define_representative',['party'],make_union(roles)],[uid])

def parse_disclosure(raw,support,out):
    text=lower_text(raw)
    protected=has_any(text,['confidential information','such confidential information','said information','information it receives from','contents of the confidential information'])
    if not protected:
        return
    actor=actor_for(text)
    if has_any(text,['neither it nor its representatives','neither the receiving party nor its representatives']) and has_any(text,['any other person','any other organization','other person or organization']):
        group=['participant_union',['receiving_party'],['representatives_of',['receiving_party']]]
        add_statement(out,['prohibition',group,['disclose',['confidential_information'],['outsiders_to',group]],['no_condition'],['no_exceptions']],support)
        return
    if has_any(text,['reveal such confidential information to others','reveal confidential information to others']):
        add_statement(out,['prohibition',actor,['disclose',['confidential_information'],['outsiders_to',actor]],['no_condition'],['exception_set',['authorization_exception','source-stated authorization']]],support)
        return
    permission=has_any(text,['may disclose','may be disclosed','may share','will disclose information','restrict disclosure','restrict access','disclosed only to','do not apply to the disclosure'])
    if permission:
        roles=recipient_roles(text,['receiving_party'])
        if roles:
            add_statement(out,['permission',actor,['disclose',['confidential_information'],make_union(roles)],disclosure_conditions(text,raw)],support)
    negative=has_any(text,['shall not disclose','not disclose said information','not to disclose','agrees not to','will not provide confidential information','prohibited from disclosing'])
    general_recipient=has_any(text,['third party','third parties','any other person','any other organization'])
    if negative and general_recipient:
        exceptions=[]
        if has_any(text,['prior written consent','prior written agreement','prior written approval','expressly authorized in writing']):
            exceptions.append(['authorization_exception','source-stated written authorization'])
        if has_any(text,['required to analyze','required to fulfil','required to fulfill','required in the course of service']):
            exceptions.append(['purpose_exception','source-stated required activity'])
        if exceptions:
            ex=['exception_set',exceptions[0]]
            i=1
            while i<len(exceptions):
                ex=['add_exception',ex,exceptions[i]]
                i+=1
        else:
            ex=['no_exceptions']
        add_statement(out,['prohibition',actor,['disclose',['confidential_information'],['third_parties']],['no_condition'],ex],support)

def information_scope(text):
    items=[['confidential_information']]
    if has_any(text,['copy','copies','reproduction','record copy','backup','archive']):
        items.append(['copies_of',['confidential_information']])
    if has_any(text,['note','abstract','extract','analysis','study','summary','derivative']):
        items.append(['derivative_materials_of',['confidential_information']])
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['information_bundle',items[i],value]
        i-=1
    return value

def trigger_terms(text):
    out=[]
    if has_any(text,['business relationship is not entered','relationship is not entered','fail to enter into a business relationship']):
        out.append(['relationship_nonformation_deadline'])
    if has_any(text,['termination of service','service terminates','termination of the actor’s service']):
        out.append(['service_termination'])
    if has_any(text,['termination/expiration of the business relation','termination or expiration of the business relation','termination of the business relationship','termination of the working relationship']):
        out.append(['relationship_termination'])
    if has_any(text,['termination of this agreement','termination ofthis agreement','expiration of this agreement','expiration or termination of this agreement','expiration or termination ofthis agreement','termination/expiration of this non-disclosure agreement']):
        out.append(['agreement_termination'])
    if 'completion of the purpose' in text:
        out.append(['purpose_completion'])
    if has_any(text,['upon request','at any time upon request','promptly upon request','request by','request of','request from']):
        out.append(['request_by',['disclosing_party']])
    return unique(out)

def trigger_value(items):
    if not items:
        return None
    value=items[0]
    i=1
    while i<len(items):
        value=['trigger_alternative',value,items[i]]
        i+=1
    return value

def has_return_action(text):
    return has_any(text,['shall return','return to','returned to','promptly return','information will be returned'])

def has_destroy_action(text):
    return has_any(text,['shall be destroyed','or destroy','destroy it','certify the destruction','ensure the destruction','promptly destroy']) and 'not destroyed' not in text

def add_disposal(raw,support,statements):
    text=low(raw)
    triggers=trigger_terms(text)
    if not triggers:
        return
    do_return=has_return_action(text)
    do_destroy=has_destroy_action(text)
    if not do_return and not do_destroy:
        return
    info=information_scope(text)
    if do_return and do_destroy:
        action=['action_alternative',['return_to',info,['disclosing_party']],['destroy',info]]
    elif do_return:
        action=['return_to',info,['disclosing_party']]
    else:
        action=['destroy',info]
    add_statement(statements,['disposal_obligation',actor_for(text),action,trigger_value(triggers),['no_exceptions']],support)

def add_retention(raw,uid,statements):
    text=low(raw)
    info=information_scope(text)
    actor=actor_for(text)
    if has_any(text,['entitled to retain','may retain','may maintain a single copy','permitted to retain']):
        add_statement(statements,['retention_permission',actor,info,['after_disposal'],['retention_condition',raw]],[uid])
    if has_any(text,['without retaining any copies','no copies, electronic or otherwise','no copies or records thereof shall be retained','no copy shall be retained']):
        add_statement(statements,['retention_prohibition',actor,info,['after_disposal']],[uid])
    if has_any(text,['not to make or retain copy','shall not retain any copy','must not retain any copy','no copies, electronic or otherwise, notes or abstracts of the foregoing shall be retained']):
        add_statement(statements,['absolute_retention_prohibition',actor,info],[uid])

def term_has(term,name):
    todo=[term]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            if item[0]==name:
                return True
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return False

def lower_text(value):
    if not isinstance(value,str):
        value=str(value)
    return value.casefold().strip()

def make_bundle(items):
    if not items:
        return ['confidential_information']
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['information_bundle',items[i],value]
        i-=1
    return value

def recipient_roles(text,owner):
    out=[]
    if has_any(text,['employee','staff','personnel']):
        out.append(['employees_of',owner])
    if 'director' in text:
        out.append(['directors_of',owner])
    if has_any(text,['officer','official']):
        out.append(['officers_of',owner])
    if has_any(text,['legal adviser','legal advisor','attorney','legal counsel']):
        out.append(['legal_advisors_of',owner])
    if has_any(text,['financial adviser','financial advisor']):
        out.append(['financial_advisors_of',owner])
    if has_any(text,['professional adviser','professional advisor']):
        out.append(['professional_advisors_of',owner])
    if 'accountant' in text:
        out.append(['accountants_of',owner])
    if 'consultant' in text:
        out.append(['consultants_of',owner])
    if 'contractor' in text:
        out.append(['independent_contractors_of',owner])
    if 'agent' in text:
        out.append(['agents_of',owner])
    if has_any(text,['lender','finance provider']):
        out.append(['lenders_of',owner])
    if not out and 'representative' in text:
        out.append(['representatives_of',owner])
    return out

def disclosure_conditions(text,raw):
    out=[]
    if has_any(text,['need to know','need-to-know','strict need to know','bona fide need']):
        out.append(['need_to_know',raw])
    if has_any(text,['extent necessary','extent absolutely necessary','reasonably necessary','disclosure is necessary','knowledge of the confidential information is reasonably necessary']):
        out.append(['extent_necessary',raw])
    if has_any(text,['written confidentiality agreement','written agreement with','signed the mandatory non-disclosure agreement','signed the mandatory nondisclosure agreement','bound to a duty of confidentiality','bound by obligations of confidentiality','treat the confidential information in accordance','treat the confidential information as confidential','advise such employees','complies with all the provisions of this agreement','obligated to protect']):
        out.append(['confidentiality_bound',raw])
    return make_and(out)

def material_scope(text):
    items=[['confidential_information']]
    if has_any(text,['copy','copies','reproduction','record copy','backup','archive']):
        items.append(['copies_of',['confidential_information']])
    if has_any(text,['note','abstract','extract','analysis','study','summary','derivative']):
        items.append(['derivative_materials_of',['confidential_information']])
    return make_bundle(items)

def parse_retention(raw,uid,out):
    text=lower_text(raw)
    actor=actor_for(text)
    info=material_scope(text)
    if has_any(text,['entitled to retain','may retain','may maintain a single copy','permitted to retain']):
        add_statement(out,['retention_permission',actor,info,['after_disposal'],['retention_condition',raw]],[uid])
    explicit_after=has_any(text,['without retaining any copies','without retaining any copy','no copies or records thereof shall be retained','no copy shall be retained']) or ('no copies' in text and 'shall be retained' in text)
    if explicit_after:
        add_statement(out,['retention_prohibition',actor,info,['after_disposal']],[uid])
    absolute=has_any(text,['not to make or retain copy','shall not retain any copy','must not retain any copy'])
    if 'will at any time' in text and 'retain' in text and 'confidential information' in text:
        absolute=True
    if 'will not' in text and 'preserve any confidential information' in text:
        absolute=True
    if absolute:
        add_statement(out,['absolute_retention_prohibition',actor,info],[uid])

